def md(s):return markdown.markdown(s,extensions=['tables','fenced_code','sane_lists'])
def table(df):return '<div class="table-wrap">'+df.to_html(index=False,na_rep='—',border=0,escape=True,float_format=lambda x:f'{x:,.2f}')+'</div>'
def fig(name,caption):
 source=R/'figures'/name
